const body = $json.body ?? $json;

const sessionId = String(body.sessionId ?? "anonymous").slice(0, 120);
const message = String(body.message ?? "").trim();
const pageContext = String(body.pageContext ?? "/").slice(0, 160);
const visitorType = String(body.visitorType ?? "unknown").slice(0, 80);

return {
  sessionId,
  message,
  pageContext,
  visitorType,
  receivedAt: new Date().toISOString(),
  isValid: message.length > 0 && message.length <= 600,
};
